package com.geekmall.search;import org.springframework.amqp.core.*;import org.springframework.context.annotation.*;
@Configuration class SearchRabbitConfiguration{static final String EX="geek.domain.events",Q="geek.search.product-index",DLX="geek.domain.events.dlx",DLQ="geek.search.product-index.dlq";@Bean DirectExchange domainExchange(){return new DirectExchange(EX,true,false);}@Bean DirectExchange deadExchange(){return new DirectExchange(DLX,true,false);}@Bean Queue productQueue(){return QueueBuilder.durable(Q).deadLetterExchange(DLX).deadLetterRoutingKey(DLQ).build();}@Bean Queue deadQueue(){return QueueBuilder.durable(DLQ).build();}@Bean Binding on(Queue productQueue){return BindingBuilder.bind(productQueue).to(domainExchange()).with("product.spu.on-sale.v1");}@Bean Binding off(Queue productQueue){return BindingBuilder.bind(productQueue).to(domainExchange()).with("product.spu.off-sale.v1");}@Bean Binding dead(Queue deadQueue){return BindingBuilder.bind(deadQueue).to(deadExchange()).with(DLQ);}}
